"""Read Thrower's firing scale table from the supplied original; never execute it."""
from pathlib import Path
from inspect_original import Original


def main():
    original = Original()
    lines = [
        '// Generated by game/tools/import_thrower_visual.py from the supplied original.',
        '// Thrower.initSprites / updateAnimation:, 20 barrel scale poses at 60 Hz.',
        '#pragma once', '#include "engine/core/geometry/vector2.h"',
        '#include <algorithm>', '#include <array>', 'namespace game::play {',
        '// ARM table 0x1ac8dc; S01 is one image, animated by scale X/Y.',
        'inline constexpr std::array<elysia::core::Vector2,20> kThrowerBarrelScale{{',
    ]
    for frame in range(20):
        x, y = original.unpack('<2f', 0x1ac8dc + frame * 8)
        def literal(value):
            text = format(value, '.6g')
            return text + ('.0f' if '.' not in text and 'e' not in text else 'f')
        lines.append('    {' + literal(x) + ',' + literal(y) + '},')
    lines += [
        '}};',
        'inline elysia::core::Vector2 thrower_barrel_scale(double seconds) {',
        '    return kThrowerBarrelScale[static_cast<std::size_t>(std::clamp(seconds*60.+1e-7,0.,19.))];',
        '}', '}',
    ]
    target = Path(__file__).resolve().parents[1] / 'gameplay/thrower_visual.h'
    target.write_text('\n'.join(lines) + '\n', encoding='utf8')
    print(target)


if __name__ == '__main__':
    main()
